#include <iostream>
#include <vector>
#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int L, C;
    if (!(cin >> L >> C)) return 0;

    vector<string> grid(L);
    int start_r = -1, start_c = -1;

    for (int i = 0; i < L; ++i) {
        cin >> grid[i];
        for (int j = 0; j < C; ++j) {
            if (grid[i][j] == 'o') {
                start_r = i;
                start_c = j;
            }
        }
    }

    vector<vector<bool>> visited(L, vector<bool>(C, false));
    int curr_r = start_r;
    int curr_c = start_c;
    visited[curr_r][curr_c] = true;

    int dr[] = {-1, 1, 0, 0};
    int dc[] = {0, 0, -1, 1};

    while (true) {
        bool moved = false;
        for (int d = 0; d < 4; ++d) {
            int nr = curr_r + dr[d];
            int nc = curr_c + dc[d];

            if (nr >= 0 && nr < L && nc >= 0 && nc < C) {
                if (!visited[nr][nc] && grid[nr][nc] == 'H') {
                    visited[nr][nc] = true;
                    curr_r = nr;
                    curr_c = nc;
                    moved = true;
                    break;
                }
            }
        }
        if (!moved) {
            break;
        }
    }

    cout << curr_r + 1 << " " << curr_c + 1 << "\n";

    return 0;
}
